h time zone)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH latest_ratings AS (\r\n        SELECT \r\n            kp.id, \r\n            kp.name, \r\n            kp.address, \r\n            kp.google_place_id, \r\n            rh.rating, \r\n            rh.total_reviews, \r\n            rh.positive_percentage, \r\n            rh.rank_score, \r\n            rh.city_rank, \r\n            rh.data_fetched_at,\r\n            ROW_NUMBER() OVER (PARTITION BY kp.id ORDER BY rh.data_fetched_at DESC) as rn\r\n        FROM kebab_places kp\r\n        JOIN ratings_history rh ON kp.id = rh.kebab_place_id\r\n        WHERE kp.city_id = p_city_id\r\n    )\r\n    SELECT \r\n        lr.id, \r\n        lr.name, \r\n        lr.address, \r\n        lr.google_place_id, \r\n        lr.rating, \r\n        lr.total_reviews, \r\n        lr.positive_percentage, \r\n        lr.rank_score, \r\n        lr.city_rank, \r\n        lr.data_fetched_at\r\n    FROM latest_ratings lr\r\n    WHERE lr.rn = 1\r\n    ORDER BY lr.rank_score DESC, lr.total_reviews DESC\r\n    LIMIT p_limit OFFSET p_offset;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v2\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) RETURNS TABLE(\\"id\\" integer, \\"name\\" character varying, \\"address\\" character varying, \\"google_place_id\\" character varying, \\"rating\\" numeric, \\"total_reviews\\" integer, \\"positive_percentage\\" numeric, \\"rank_score\\" numeric, \\"city_rank\\" integer, \\"data_fetched_at\\" timestamp with time zone)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH latest_ratings AS (\r\n        SELECT \r\n            kp.id, \r\n            kp.name, \r\n            kp.address, \r\n            kp.google_place_id, \r\n            rh.rating, \r\n            rh.total_reviews, \r\n            rh.positive_percentage, \r\n            rh.rank_score, \r\n            rh.city_rank, \r\n            rh.data_fetched_at,\r\n            ROW_NUMBER() OVER (PARTITION BY kp.id ORDER BY rh.data_fetched_at DESC) as rn\r\n        FROM kebab_places kp\r\n        JOIN ratings_history rh ON kp.id = rh.kebab_place_id\r\n        WHERE kp.city_id = p_city_id\r\n    )\r\n    SELECT \r\n        lr.id, \r\n        lr.name, \r\n        lr.address, \r\n        lr.google_place_id, \r\n        lr.rating, \r\n        lr.total_reviews, \r\n        lr.positive_percentage, \r\n        lr.rank_score, \r\n        lr.city_rank, \r\n        lr.data_fetched_at\r\n    FROM latest_ratings lr\r\n    WHERE lr.rn = 1\r\n    ORDER BY lr.rank_score DESC, lr.total_reviews DESC\r\n    LIMIT p_limit OFFSET p_offset;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v2\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v3\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) RETURNS TABLE(\\"id\\" integer, \\"name\\" character varying, \\"address\\" \\"text\\", \\"google_place_id\\" \\"text\\", \\"rating\\" numeric, \\"total_reviews\\" integer, \\"positive_percentage\\" numeric, \\"rank_score\\" numeric, \\"city_rank\\" integer, \\"data_fetched_at\\" timestamp with time zone)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH latest_ratings AS (\r\n        SELECT \r\n            kp.id,\r\n            kp.name,\r\n            kp.address,\r\n            kp.google_place_id,\r\n            rh.rating,\r\n            rh.total_reviews,\r\n            rh.positive_percentage,\r\n            rh.rank_score,\r\n            rh.city_rank,\r\n            rh.data_fetched_at,\r\n            ROW_NUMBER() OVER (PARTITION BY kp.id ORDER BY rh.data_fetched_at DESC) as rn\r\n        FROM \r\n            kebab_places kp\r\n        JOIN \r\n            ratings_history rh ON kp.id = rh.kebab_place_id\r\n        WHERE \r\n            kp.city_id = p_city_id\r\n    )\r\n    SELECT \r\n        lr.id,\r\n        lr.name,\r\n        lr.address,\r\n        lr.google_place_id,\r\n        lr.rating,\r\n        lr.total_reviews,\r\n        lr.positive_percentage,\r\n        lr.rank_score,\r\n        lr.city_rank,\r\n        lr.data_fetched_at\r\n    FROM \r\n        latest_ratings lr\r\n    WHERE \r\n        lr.rn = 1\r\n    ORDER BY\r\n        lr.rank_score DESC,\r\n        lr.total_reviews DESC\r\n    LIMIT p_limit\r\n    OFFSET p_offset;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v3\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v4\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) RETURNS TABLE(\\"id\\" integer, \\"name\\" character varying, \\"address\\" \\"text\\", \\"google_place_id\\" character varying, \\"rating\\" numeric, \\"total_reviews\\" integer, \\"positive_percentage\\" numeric, \\"rank_score\\" numeric, \\"city_rank\\" integer, \\"data_fetched_at\\" timestamp without time zone)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH latest_ratings AS (\r\n        SELECT \r\n            kp.id,\r\n            kp.name,\r\n            kp.address,\r\n            kp.google_place_id,\r\n            rh.rating,\r\n            rh.total_reviews,\r\n            rh.positive_percentage,\r\n            rh.rank_score,\r\n            rh.city_rank,\r\n            rh.data_fetched_at,\r\n            ROW_NUMBER() OVER (PARTITION BY kp.id ORDER BY rh.data_fetched_at DESC) as rn\r\n        FROM \r\n            kebab_places kp\r\n        JOIN \r\n            ratings_history rh ON kp.id = rh.kebab_place_id\r\n        WHERE \r\n            kp.city_id = p_city_id\r\n    )\r\n    SELECT \r\n        lr.id,\r\n        lr.name,\r\n        lr.address,\r\n        lr.google_place_id,\r\n        lr.rating,\r\n        lr.total_reviews,\r\n        lr.positive_percentage,\r\n        lr.rank_score,\r\n        lr.city_rank,\r\n        lr.data_fetched_at\r\n    FROM \r\n        latest_ratings lr\r\n    WHERE \r\n        lr.rn = 1\r\n    ORDER BY\r\n        lr.rank_score DESC,\r\n        lr.total_reviews DESC\r\n    LIMIT p_limit\r\n    OFFSET p_offset;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_city_rankings_with_latest_ratings_v4\\"(\\"p_city_id\\" integer, \\"p_limit\\" integer, \\"p_offset\\" integer) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_previous_city_rankings\\"(\\"p_city_id\\" integer, \\"p_target_date\\" timestamp with time zone) RETURNS TABLE(\\"google_place_id\\" character varying, \\"city_rank\\" integer, \\"data_fetched_at\\" timestamp without time zone, \\"is_approximate\\" boolean)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH ranked_history AS (\r\n        SELECT \r\n            kp.google_place_id,\r\n            rh.city_rank,\r\n            rh.data_fetched_at,\r\n            ROW_NUMBER() OVER (\r\n                PARTITION BY kp.id \r\n                ORDER BY ABS(EXTRACT(EPOCH FROM (rh.data_fetched_at - p_target_date)))\r\n            ) as proximity_rank\r\n        FROM kebab_places kp\r\n        JOIN ratings_history rh ON rh.kebab_place_id = kp.id\r\n        WHERE kp.city_id = p_city_id\r\n        AND rh.data_fetched_at <= p_target_date\r\n    )\r\n    SELECT \r\n        rh.google_place_id,\r\n        rh.city_rank,\r\n        rh.data_fetched_at,\r\n        CASE \r\n            WHEN ABS(EXTRACT(EPOCH FROM (rh.data_fetched_at - p_target_date))) > 86400 \r\n            THEN true \r\n            ELSE false \r\n        END as is_approximate\r\n    FROM ranked_history rh\r\n    WHERE rh.proximity_rank = 1;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_previous_city_rankings\\"(\\"p_city_id\\" integer, \\"p_target_date\\" timestamp with time zone) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_previous_rankings\\"(\\"p_kebab_place_id\\" integer, \\"p_days_ago\\" integer DEFAULT 7) RETURNS TABLE(\\"previous_rank\\" integer, \\"rank_change\\" integer, \\"data_fetched_at\\" timestamp without time zone)\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nBEGIN\r\n    RETURN QUERY\r\n    WITH current_rank AS (\r\n        SELECT rh.city_rank\r\n        FROM ratings_history rh\r\n        WHERE rh.kebab_place_id = p_kebab_place_id\r\n        ORDER BY rh.data_fetched_at DESC\r\n        LIMIT 1\r\n    ),\r\n    previous_rank AS (\r\n        SELECT \r\n            rh.city_rank,\r\n            rh.data_fetched_at,\r\n            (SELECT city_rank FROM current_rank) - rh.city_rank AS change\r\n        FROM ratings_history rh\r\n        WHERE rh.kebab_place_id = p_kebab_place_id\r\n        AND rh.data_fetched_at <= (NOW() - (p_days_ago || ' days')::interval)\r\n        ORDER BY rh.data_fetched_at DESC\r\n        LIMIT 1\r\n    )\r\n    SELECT \r\n        pr.city_rank as previous_rank,\r\n        pr.change as rank_change,\r\n        pr.data_fetched_at\r\n    FROM previous_rank pr;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_previous_rankings\\"(\\"p_kebab_place_id\\" integer, \\"p_days_ago\\" integer) OWNER TO \\"postgres\\"","CREATE OR REPLACE FUNCTION \\"public\\".\\"get_rank_change_indicator\\"(\\"p_kebab_place_id\\" integer, \\"p_days_ago\\" integer DEFAULT 7) RETURNS \\"text\\"\n    LANGUAGE \\"plpgsql\\"\n    AS $$\r\nDECLARE\r\n    v_change integer;\r\n    v_previous_exists boolean;\r\nBEGIN\r\n    SELECT (rank_change IS NOT NULL) INTO v_previous_exists\r\n    FROM get_previous_rankings(p_kebab_place_id, p_days_ago);\r\n    \r\n    IF NOT v_previous_exists THEN\r\n        RETURN 'new';\r\n    END IF;\r\n    \r\n    SELECT rank_change INTO v_change\r\n    FROM get_previous_rankings(p_kebab_place_id, p_days_ago);\r\n    \r\n    RETURN CASE \r\n        WHEN v_change > 2 THEN 'up'\r\n        WHEN v_change < -2 THEN 'down' \r\n        ELSE 'neutral'\r\n    END;\r\nEND;\r\n$$","ALTER FUNCTION \\"public\\".\\"get_rank_change_indicator\\"(\\"p_kebab_place_id\\" integer, \\"p_days_ago\\" integer) OWNER TO \\"postgres\\"","SET default_tablespace = ''","SET default_table_access_method = \\"heap\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"ai_analysis\\" (\n    \\"id\\" integer NOT NULL,\n    \\"kebab_place_id\\" integer,\n    \\"analysis_type\\" character varying(50) NOT NULL,\n    \\"analysis_data\\" \\"jsonb\\" NOT NULL,\n    \\"ai_score\\" double precision DEFAULT 0,\n    \\"ai_summary\\" \\"text\\",\n    \\"confidence_score\\" double precision DEFAULT 0,\n    \\"review_count\\" integer DEFAULT 0,\n    \\"created_at\\" timestamp with time zone DEFAULT \\"now\\"(),\n    \\"updated_at\\" timestamp with time zone DEFAULT \\"now\\"()\n)","ALTER TABLE \\"public\\".\\"ai_analysis\\" OWNER TO \\"postgres\\"","CREATE SEQUENCE IF NOT EXISTS \\"public\\".\\"ai_analysis_id_seq\\"\n    AS integer\n    START WITH 1\n    INCREMENT BY 1\n    NO MINVALUE\n    NO MAXVALUE\n    CACHE 1","ALTER SEQUENCE \\"public\\".\\"ai_analysis_id_seq\\" OWNER TO \\"postgres\\"","ALTER SEQUENCE \\"public\\".\\"ai_analysis_id_seq\\" OWNED BY \\"public\\".\\"ai_analysis\\".\\"id\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"cities\\" (\n    \\"id\\" integer NOT NULL,\n    \\"name\\" character varying(100) NOT NULL,\n    \\"google_place_id\\" character varying(255),\n    \\"created_at\\" timestamp without time zone DEFAULT CURRENT_TIMESTAMP\n)","ALTER TABLE \\"public\\".\\"cities\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"kebab_places\\" (\n    \\"id\\" integer NOT NULL,\n    \\"google_place_id\\" character varying(255) NOT NULL,\n    \\"name\\" character varying(255) NOT NULL,\n    \\"address\\" \\"text\\",\n    \\"city_id\\" integer,\n    \\"latitude\\" numeric(10,8),\n    \\"longitude\\" numeric(11,8),\n    \\"created_at\\" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,\n    \\"updated_at\\" timestamp without time zone DEFAULT CURRENT_TIMESTAMP\n)","ALTER TABLE \\"public\\".\\"kebab_places\\" OWNER TO \\"postgres\\"","CREATE TABLE IF NOT EXISTS \\"public\\".\\"ratings_history\\" (\n    \\"id\\" integer NOT NULL,\n    \\"kebab_place_id\\" integer,\n    \\"rating\\" numeric(2,1),\n    \\"total_reviews\\" integer,\n    \\"positive_percentage\\" numeric(5,2),\n    \\"rank_score\\" numeric(10,2),\n    \\"city_rank\\" integer,\n    \\"global_rank\\" integer,\n    \\"data_fetched_at\\" timestamp without time zone DEFAULT CURRENT_TIMESTAMP,\n    \\"ai_score\\" double precision,\n    \\"ai_confidence\\" double precision,\n    \\"sentiment_score\\" double precision,\n    \\"authenticity_score\\" double precision,\n    \\"trend_momentum\\" double precision,\n    \\"update_batch_timestamp\\" timestamp with time zone\n)","ALTER TABLE \\"public\\".\\"ratings_history\\" OWNER TO \\"postgres\\"","CREATE OR REPLACE VIEW \\"public\\".\\"ai_rankings\\" AS\n SELECT \\"kp\\".\\"id\\",\n    \\"kp\\".\\"name\\",\n    \\"kp\\".\\"address\\",\n    \\"kp\\".\\"google_place_id\\",\n    \\"c\\".\\"name\\" AS \\"city_name\\",\n    \\"rh\\".\\"rating\\",\n    \\"rh\\".\\"total_reviews\\",\n    \\"rh\\".\\"rank_score\\",\n    \\"rh\\".\\"city_rank\\",\n    COALESCE(\\"rh\\".\\"ai_score\\", (\\"rh\\".\\"rank_score\\")::double precision) AS \\"combined_score\\",\n    (\\"aa\\".\\"analysis_data\\" ->> 'sentiment_analysis'::\\"text\\") AS \\"sentiment_data\\",\n    (\\"aa\\".\\"analysis_data\\" ->> 'trend_analysis'::\\"text\\") AS \\"trend_data\\",\n    \\"aa\\".\\"ai_summary\\",\n    \\"aa\\".\\"confidence_score\\" AS \\"ai_confidence\\",\n    \\"aa\\".\\"updated_at\\" AS \\"ai_last_updated\\"\n   FROM (((\\"public\\".\\"kebab_places\\" \\"kp\\"\n     JOIN \\"public\\".\\"cities