20260213000802	{"-- Allow anyone to upload to 'kebab-photos' bucket\n-- Note: This is safe for a hobby project but keep in mind anyone with your URL can upload if they know the bucket name.\nDO $$\nBEGIN\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_policies \n        WHERE tablename = 'objects' AND schemaname = 'storage' AND policyname = 'Public Upload Kebab Photos'\n    ) THEN\n        CREATE POLICY \\"Public Upload Kebab Photos\\"\n        ON storage.objects FOR INSERT\n        TO public\n        WITH CHECK (bucket_id = 'kebab-photos');\n    END IF;\n\n    IF NOT EXISTS (\n        SELECT 1 FROM pg_policies \n        WHERE tablename = 'objects' AND schemaname = 'storage' AND policyname = 'Public Access Kebab Photos'\n    ) THEN\n        CREATE POLICY \\"Public Access Kebab Photos\\"\n        ON storage.objects FOR SELECT\n        TO public\n        USING (bucket_id = 'kebab-photos');\n    END IF;\nEND $$;\n"}	storage_policies_for_kebab_photos	kryptoholik@gmail.com	\N	\N
